def sty(fig, h=380, title=None):
    """one look for every chart"""
    fig.update_layout(template="plotly_dark", height=h, paper_bgcolor=CARD, plot_bgcolor=CARD,
                      font=dict(family="Segoe UI, Arial", color=TXT, size=12), margin=dict(t=60, b=20, l=50, r=40),
                      title=dict(text=title, x=0.01, font=dict(size=15)) if title else None,
                      legend=dict(orientation="h", y=1.12, x=0.0))
    fig.update_xaxes(gridcolor=GRID, zeroline=False); fig.update_yaxes(gridcolor=GRID, zeroline=False)
    return fig

def dtable(d):
    def c(v):
        v = str(v); k = "p" if v.startswith("+") else "n" if v.startswith("-") and len(v) > 1 else ""
        return f'<td class="{k}">{v}</td>'
    h = "".join(f"<th>{x}</th>" for x in d.columns)
    r = "".join("<tr>" + "".join(c(v) for v in row) + "</tr>" for row in d.itertuples(index=False))
    st.markdown(f'<div style="overflow-x:auto"><table class="dt"><tr>{h}</tr>{r}</table></div>', unsafe_allow_html=True)

# ───────────────────────── data ─────────────────────────
def ra_segment(b, seg, var, pack, our):
    if seg in ("(blank)", "CADBURY", "OTHERS", "COOKIES", "POWDER"): return "Others"
    if seg in ("MINIATURES", "GIFT BOX"): return "Praline"
    if seg == "BITE SIZE": return "Bite Size"
    if seg == "WAFER": return "Countline Wafer"
    if seg == "CARAMEL": return "Countline Regular"
    if seg == "CRUNCHY":
        return "Tablet" if (our == "Y" or str(b).startswith("CANDYLAND") or b == "MITCHELLS") else "Countline Regular"
    if seg == "FRUIT & NUT" and var == "WHOLENUT" and our == "N": return "Countline Regular"
    return "Tablet"

def read_extra(src, name):
    df = pd.read_csv(src) if name.lower().endswith((".csv", ".gz")) else pd.read_excel(src)
    if "Alfatah" not in df.columns:
        vc = next((c for c in ("Value", "VALUE", "ALL") if c in df.columns), None)
        if vc is None: raise ValueError("Need an 'Alfatah' (or 'Value') column")
        df["Alfatah"] = df[vc]
    return df

@st.cache_data(show_spinner="Loading data…")
def load(extra_bytes=None, extra_name=None):
    df = pd.read_csv(_emb(EPOS_B64), compression="gzip", dtype={"GRAMMAGE": str})
    for r in BASE_RETAILERS: df[r] = pd.to_numeric(df[r], errors="coerce").fillna(0)
    df["Alfatah"] = 0.0
    ex = None
    if extra_bytes is not None: ex = read_extra(io.BytesIO(extra_bytes), extra_name)
    else:
        for f in ("alfatah.csv", "alfatah.csv.gz", "alfatah.xlsx"):
            if os.path.exists(os.path.join(D, f)): ex = read_extra(os.path.join(D, f), f); break
    if ex is not None:
        ex["GRAMMAGE"] = ex["GRAMMAGE"].astype(str)
        for r in BASE_RETAILERS:
            ex[r] = 0.0
        df = pd.concat([df, ex[[c for c in df.columns if c in ex.columns]]], ignore_index=True).fillna({r: 0 for r in BASE_RETAILERS + ["Alfatah"]})
    mp = pd.read_csv(_emb(SEGMAP_B64))
    k = ["BRAND_DESC", "SEGMENT_DESC", "VARIANT_DESC", "PACK_DESC"]
    df = df.merge(mp, on=k, how="left")
    miss = df["RA_SEGMENT"].isna()
    df.loc[miss, "RA_SEGMENT"] = [ra_segment(*r) for r in df.loc[miss, k + ["OUR COMPANY"]].itertuples(index=False, name=None)]
    pl = pd.read_csv(_emb(PRICE_B64), dtype={"GRAMMAGE": str})
    df = df.merge(pl, on=["BRAND_DESC", "VARIANT_DESC", "PACK_DESC", "GRAMMAGE"], how="left")
    df["PRICE_POINT"] = "Unmapped"
    for lab, (n, a, b) in zip(PRICE_LABELS, PRICE_SLABS):
        df.loc[df.PRICE.between(a, b), "PRICE_POINT"] = lab
    df["GRAM_NUM"] = pd.to_numeric(df["GRAMMAGE"], errors="coerce")
    df["MDLZ"] = df["OUR COMPANY"].eq("Y")
    return df

