glabs = [f"≤{edges[0]:g}g"] + [f"{a:g}–{b:g}g" for a, b in zip(edges, edges[1:])] + [f">{edges[-1]:g}g"]
df["GRAM_SLAB"] = pd.cut(df.GRAM_NUM, [-1] + edges + [1e9], labels=glabs).astype(object).fillna("Unknown")
RETAILERS = BASE_RETAILERS + (["Alfatah"] if df["Alfatah"].abs().sum() > 0 else [])

# ───────────────────────── filters ─────────────────────────
def ms(col, label, c, options=None):
    opts = options or sorted(df[col].dropna().astype(str).unique())
    return c.multiselect(label, opts, key=label, placeholder="All")

with st.expander("🔎 Filters", expanded=True):
    r1 = st.columns(5)
    sel_ret = r1[0].multiselect("Retailer", RETAILERS, default=RETAILERS, key="ret") or RETAILERS
    years = sorted(df.Year.unique())
    year = r1[1].selectbox("Year", years, index=len(years) - 1)
    df["VAL"] = df[sel_ret].sum(axis=1)
    has = df[(df.Year == year) & (df.VAL > 0)]
    data_m = int(has.Month.max()) if len(has) else 12
    full = has[has.BRAND_DESC == "OTHERS"]          # 'OTHERS' rows carry the market total -> needed for a valid share
    last_m = int(full.Month.max()) if len(full) else data_m
    kind = r1[2].selectbox("Period", ["YTD", "Full year", "H1", "H2", "Q1", "Q2", "Q3", "Q4", "Custom months"])
    custom = r1[3].multiselect("Months (for Custom)", MON, default=MON[:last_m], disabled=kind != "Custom months")
    r1[4].markdown(f"<br>Latest complete month: **{MON[last_m-1]} {year}**", unsafe_allow_html=True)
    if data_m > last_m:
        st.warning(f"Source data after {MON[last_m-1]} {year} has no 'OTHERS' (total-market) rows, so shares for {MON[last_m]}–{MON[data_m-1]} {year} "
                   "are overstated. YTD is capped at the last complete month; add the missing market-total rows to extend it.")
    r2 = st.columns(4)
    f_brand = ms("BRAND_DESC", "Brand", r2[0]); f_seg = ms("RA_SEGMENT", "Segment (Retail Access)", r2[1], SEGMENTS)
    f_price = ms("PRICE_POINT", "Price point", r2[2], PRICE_LABELS + ["Unmapped"])
    f_gram = ms("GRAM_SLAB", "Grammage slab", r2[3], glabs + ["Unknown"])
    r3 = st.columns(4)
    f_var = ms("VARIANT_DESC", "Variant", r3[0]); f_pack = ms("PACK_DESC", "Pack", r3[1]); f_loc = ms("LOCAL", "Origin", r3[2])
    if r3[3].button("Reset filters"):
        for k in list(st.session_state.keys()): del st.session_state[k]
        st.rerun()

def apply(d):
    for col, sel in (("BRAND_DESC", f_brand), ("RA_SEGMENT", f_seg), ("PRICE_POINT", f_price), ("GRAM_SLAB", f_gram),
                     ("VARIANT_DESC", f_var), ("PACK_DESC", f_pack), ("LOCAL", f_loc)):
        if sel: d = d[d[col].isin(sel)]
    return d
dff = apply(df)

PM = {"Full year": range(1, 13), "YTD": range(1, last_m + 1), "H1": range(1, 7), "H2": range(7, 13),
      "Q1": range(1, 4), "Q2": range(4, 7), "Q3": range(7, 10), "Q4": range(10, 13),
      "Custom months": [MON.index(m) + 1 for m in custom]}
months = list(PM[kind]) or [last_m]
plabel = f"{kind} {year}" + (f" ({MON[months[0]-1]}–{MON[months[-1]-1]})" if kind in ("YTD",) else "")

def monthly(d, y):
    g = d[d.Year == y].groupby("Month")["VAL"].sum()
    return np.array([g.get(m, 0.0) for m in range(1, 13)])
def pct(a, b): return None if not b else (a - b) / abs(b) * 100
def mio(v): return "—" if v is None else f"{v/1e6:.2f}".rstrip("0").rstrip(".") if abs(v) >= 5e3 else f"{v/1e6:.2f}"
def fp(v, pp=False, dec=1):
    if v is None or (isinstance(v, float) and np.isnan(v)): return "—"
    return f"{v:+.{2 if pp else dec}f}{' pp' if pp else '%'}"
def cls(v): return "neu" if v is None else "pos" if v > 0 else "neg" if v < 0 else "neu"
def tot_mdlz(d, y, ms_):
    x = d[(d.Year == y) & d.Month.isin(ms_)]
    return x.VAL.sum(), x[x.MDLZ].VAL.sum()

def period_stats(d, y, ms_):
    t, m = tot_mdlz(d, y, ms_); tp, mp_ = tot_mdlz(d, y - 1, ms_)
    sh = m / t * 100 if t else None; shp = mp_ / tp * 100 if tp else None
    return dict(tot=t, mdlz=m, tot_py=tp, mdlz_py=mp_, share=sh, share_py=shp,
                growth=pct(m, mp_), tgrowth=pct(t, tp), delta=(sh - shp) if sh is not None and shp is not None else None)

# ───────────────────────── 1. callouts ─────────────────────────
S = period_stats(dff, year, months)
