# ───────────────────────── 3. market share ─────────────────────────
st.header("Mondelez market share %")
def share_series(d, y):
    t = monthly(d, y); m = monthly(d[d.MDLZ], y)
    return np.where(t > 0, m / np.where(t > 0, t, 1) * 100, np.nan)
scy, spy = share_series(dff, year), share_series(dff, year - 1)
gl = scy - spy
fig = go.Figure([go.Scatter(x=MON, y=scy, name=f"{year} share %", line=dict(color=NAVY, width=3), mode="lines+markers"),
                 go.Scatter(x=MON, y=spy, name=f"{year-1} share %", line=dict(color=GREY, dash="dash"), mode="lines+markers"),
                 go.Bar(x=MON, y=gl, name="Gain/Loss (pp)", yaxis="y2", opacity=.6,
                        marker_color=["#34D399" if (v >= 0) else "#FB7185" for v in np.nan_to_num(gl)])])
fig.update_layout(yaxis=dict(title="Share %"), yaxis2=dict(title="pp", overlaying="y", side="right", showgrid=False))
st.plotly_chart(sty(fig, 380, "Mondelez value share % – CY vs PY"), use_container_width=True)
f1 = lambda v: "—" if np.isnan(v) else f"{v:.1f}%"
t2 = pd.DataFrame({"": [f"{year} (CY)", f"{year-1} (PY)", "Gain / Loss (pp)"]})
for i, m in enumerate(MON): t2[m] = [f1(scy[i]), f1(spy[i]), "—" if np.isnan(gl[i]) else f"{gl[i]:+.2f}"]
t2["Period"] = [f1(S["share"] or np.nan), f1(S["share_py"] or np.nan), "—" if S["delta"] is None else f"{S['delta']:+.2f}"]
