# ───────────────────────── 4. share gain/loss ─────────────────────────
st.header("Share gain / loss – dynamic comparison")
DIMS = {"Brand": "BRAND_DESC", "Segment (Retail Access)": "RA_SEGMENT", "Variant": "VARIANT_DESC", "Pack": "PACK_DESC",
        "Origin": "LOCAL", "Price point": "PRICE_POINT", "Grammage slab": "GRAM_SLAB", "SKU": "SKU_ID"}
yrs_all = sorted(dff.Year.unique())
pm, py_ = (last_m - 1, year) if last_m > 1 else (12, year - 1)
g = st.columns(6)
by = g[0].selectbox("Base year", yrs_all, index=yrs_all.index(py_) if py_ in yrs_all else 0)
bm = g[1].selectbox("Base month", MON, index=pm - 1)
cyr = g[2].selectbox("Comparison year", yrs_all, index=yrs_all.index(year))
