def dshare(y, m):
    x = dff[(dff.Year == y) & (dff.Month == MON.index(m) + 1)]
    t = x.VAL.sum(); s = x.groupby(DIMS[dim]).VAL.sum()
    return (s / t * 100 if t else s * 0), x.groupby(DIMS[dim]).MDLZ.max()
sb, _ = dshare(by, bm); sc, mflag = dshare(cyr, cmo)
cmp_ = pd.DataFrame({"base": sb, "comp": sc}).fillna(0)
cmp_["delta"] = cmp_.comp - cmp_.base
isM = dff.groupby(DIMS[dim]).MDLZ.max(); cmp_["MDLZ"] = isM.reindex(cmp_.index).fillna(False)
cmp_ = cmp_[cmp_.delta.abs() > 1e-4].reindex(cmp_.delta.abs().sort_values(ascending=False).index).head(topn).iloc[::-1]
if cmp_.empty: st.info("No data for the selected months.")
else:
    fig = go.Figure(go.Bar(y=cmp_.index.astype(str).str.replace("||", " · ", regex=False), x=cmp_.delta, orientation="h",
                           marker_color=[NAVY if m else RED for m in cmp_.MDLZ],
                           customdata=cmp_[["base", "comp"]].values,
                           hovertemplate="%{y}<br>Δ %{x:+.3f} pp<br>Base %{customdata[0]:.2f}% → Comp %{customdata[1]:.2f}%<extra></extra>"))
    fig.update_layout(xaxis_title="Share change (pp)")
